  Hypothesis TOK : x2_table_ok cells tl.
  Hypothesis ECB : cbs = firstn (Z.to_nat (4 * 2^tl)) (x2_bytes' cells).
  Hypothesis LCB : zlen cbs = 4 * 2^tl.
  Hypothesis MTL : 1 <= mtl <= 12.
  Hypothesis TLM : tl <= mtl.
  Hypothesis D0 : 0 <= DST.
  Hypothesis DP : 0 < dcap -> 8 <= DST.
  Hypothesis DC : 0 <= dcap < 2^32.
  Hypothesis DL : DST + dcap <= lo.
  Hypothesis S0 : 16 <= SS.
  Hypothesis SL : SS + n <= lo.
  Hypothesis NSM : n < 2^26.
  Hypothesis BYS : Forall (fun c => 0 <= c < 256) src.
  Hypothesis DT0 : 0 < DT.
  Hypothesis CBL : DT + 4 + 4 * 2^tl <= lo.
  Hypothesis DJ1 : DT + 4 + 4 * 2^tl <= DST \/ DST + dcap <= DT.
  Hypothesis DJ3 : DST + dcap <= SS \/ SS + n <= DST.
  Hypothesis LOS : lo <= SP - 4096.
  Hypothesis SP16 : SP mod 16 = 0.
  Hypothesis SP47 : SP <= 2^47.

  Notation POST := (huf_dec_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc DST dcap lo m0).
  Notation YB l := (l ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m0 DST dcap SS DT mtl tl lo src cells cbs
                      TOK ECB LCB MTL TLM D0 DP DC DL S0 SL NSM BYS DT0 CBL DJ1 DJ3 LOS SP16 SP47) (only parsing).
  Notation X4F' mm spl bd4 := (X4F ra sp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 m0 DST dcap SS DT lo src cbs mm spl bd4).

  Notation DW := [(SP - 4096, SP); (DST, DST + dcap)].
  Notation Y4S' mm := (Y4S ra sp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 m0 DST dcap SS DT mtl tl lo src cbs mm).
  Notation L1 := (jt_len src 0). Notation L2 := (jt_len src 2). Notation L3 := (jt_len src 4).
  Notation SEG := ((dcap + 3) / 4).
  (* [comment removed for export] *)
  Notation SPL0 j0 j8 j16 j24 j32 j40 j48 j56 j64 j72 j80 j88 j96 j104 j112 j120 j128 j136 j144 j152 :=
    [CB 8 j0; CB 8 j8; CB 8 j16; CB 8 j24; CB 8 j32; CB 8 j40; CB 8 j48; CB 8 j56; CB 8 j64; CB 8 j72; CB 8 j80; CB 8 j88;
     CB 8 j96; CB 8 j104; CB 8 j112; CB 8 j120; CB 8 j128; CB 8 j136; CB 8 j144; CB 8 j152].
  Notation FR0 mm j0 j8 j16 j24 j32 j40 j48 j56 j64 j72 j80 j88 j96 j104 j112 j120 j128 j136 j144 j152 jb :=
    (X4F' mm (SPL0 j0 j8 j16 j24 j32 j40 j48 j56 j64 j72 j80 j88 j96 j104 j112 j120 j128 j136 j144 j152) [CB 40 jb]).
  Notation FACTS0 := (6 <= dcap /\ 10 <= n /\ 1 <= L1 /\ L1 + L2 + L3 + 6 <= n /\ 3 * SEG <= dcap /\ 0 <= L2 /\ 0 <= L3).

  (* [comment removed for export] *)
  Notation P1 pc mm xra t0 t1 t2 a0 a5 a6 a7 x23 x24 x26 x27 :=
    (MS (mkR xra (Z_to_bv 64 (SP + -416)) gp tp t0 t1 t2 (Z_to_bv 64 DST) (Z_to_bv 64 dcap) a0
             (Z_to_bv 64 L2) (Z_to_bv 64 (L1 + L2 + L3 + 6)) (Z_to_bv 64 L3) (Z_to_bv 64 L1) a5 a6 a7
             (Z_to_bv 64 (tl + 256 * mtl)) (Z_to_bv 64 DT) (Z_to_bv 64 (SS + 6 + L1)) (Z_to_bv 64 SS) (Z_to_bv 64 (DST + 2 * SEG))
             x23 x24 (Z_to_bv 64 (DST + dcap)) x26 x27 (Z_to_bv 64 (DST + 3 * SEG)) (Z_to_bv 64 (SS + 6)) (Z_to_bv 64 n)
             (Z_to_bv 64 (DST + SEG)))
        F (Z_to_bv 64 pc) fc None mm (seg_rom psegs)).


  (* [comment removed for export] *)
  Notation P2 pc mm xra t0 t1 a0 a4 a5 a6 a7 x24 x27 pa1 bc1 c1 :=
    (MS (mkR xra (Z_to_bv 64 (SP + -416)) gp tp t0 t1 (Z_to_bv 64 bc1) (Z_to_bv 64 DST) (Z_to_bv 64 dcap) a0
             (Z_to_bv 64 L2) (Z_to_bv 64 (L1 + L2 + L3 + 6)) (Z_to_bv 64 L3) a4 a5 a6 a7
             (Z_to_bv 64 (tl + 256 * mtl)) (Z_to_bv 64 DT) (Z_to_bv 64 (SS + 6 + L1)) (Z_to_bv 64 SS) (Z_to_bv 64 (DST + 2 * SEG))
             c1 x24 (Z_to_bv 64 (DST + dcap)) (Z_to_bv 64 pa1) x27 (Z_to_bv 64 (DST + 3 * SEG)) (Z_to_bv 64 (SS + 6)) (Z_to_bv 64 n)
             (Z_to_bv 64 (DST + SEG)))
        F (Z_to_bv 64 pc) fc None mm (seg_rom psegs)).
  Notation FR2 mm j0 j8 j16 j24 j32 j40 j48 j56 j64 j72 j80 j88 j96 j112 j120 j128 j136 j144 j152 jb :=
    (X4F' mm [CB 8 j0; CB 8 j8; CB 8 j16; CB 8 j24; CB 8 j32; CB 8 j40; CB 8 j48; CB 8 j56; CB 8 j64; CB 8 j72; CB 8 j80;
              CB 8 j88; CB 8 j96; C8 (Z_to_bv 64 dcap); CB 8 j112; CB 8 j120; CB 8 j128; CB 8 j136; CB 8 j144; CB 8 j152]
             [CB 40 jb]).

  Hypothesis CONT2 : forall mm pa1 bc1 j0 j8 j16 j24 j32 j40 j48 j56 j64 j72 j80 j88 j96 j112 j120 j128 j136 j144 j152 jb
                            (xra t0 t1 a0 a4 a5 a6 a7 x24 x27 c1 : word),
    FR2 mm j0 j8 j16 j24 j32 j40 j48 j56 j64 j72 j80 j88 j96 j112 j120 j128 j136 j144 j152 jb -> FACTS0 ->
    Y0HDI L1 (pa1 - (SS + 6)) bc1 ->
    evt psegs POST (P2 0x161c0 mm xra t0 t1 a0 a4 a5 a6 a7 x24 x27 pa1 bc1 c1).

  Ltac rd_src6 S bs :=
    lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mg _) =>
    tryif (match goal with _ : ov_read_bytes psegs mg (Z_to_bv 64 (S + 7)) 1 = Some _ |- _ => idtac end) then idtac
    else (
    repeat match goal with H : ov_read_bytes psegs _ (Z_to_bv 64 (S + _)) 1 = Some _ |- _ => clear H end;
    lazymatch goal with
    | H : bytes_at psegs mg S (map (Z_to_bv 8) bs) |- _ =>
      let t k := tryif (assert (k < zlen bs) by lia) then pose proof (src_rd psegs mg S bs k H ltac:(lia)) else idtac in
      t 7; t 8; t 9; t 10; t 11; t 12
    end) end.
  Ltac dec_if := lazymatch goal with |- evt _ _ (MS _ _ (if ?c then _ else _) _ _ _ _) =>
    let b := eval vm_compute in c in change c with b; cbv iota end.
  Ltac step_to S bs pc := repeat (lazymatch goal with
     | |- evt _ _ (MS _ _ (Z_to_bv 64 pc) _ _ _ _) => fail
     | |- evt _ _ (MS _ _ (if _ then _ else _) _ _ _ _) => dec_if
     | |- evt _ _ (MS _ _ _ _ _ _ _) => rd_src6 S bs; zstep end).

  (* [comment removed for export] *)
  Lemma y4s01_join : forall len mm j0 j8 j16 j24 j32 j40 j48 j56 j64 j72 j80 j88 j96 j112 j120 j128 j136 j144 j152 jb
                            (xra t0 t1 t2 a0 a2 a5 a6 a7 x24 x26 x27 c1 : word),
    len = L1 -> 1 <= len <= 7 -> a2 = (Z_to_bv 64 (L1 + L2 + L3 + 6)) ->
    FR2 mm j0 j8 j16 j24 j32 j40 j48 j56 j64 j72 j80 j88 j96 j112 j120 j128 j136 j144 j152 jb -> FACTS0 ->
    evt psegs POST (MS (mkR xra (Z_to_bv 64 (SP + -416)) gp tp t0 t1 t2 (Z_to_bv 64 DST) (Z_to_bv 64 dcap) a0
                           (Z_to_bv 64 L2) a2 (Z_to_bv 64 L3) (Z_to_bv 64 len) a5 a6 a7
                           (Z_to_bv 64 (tl + 256 * mtl)) (Z_to_bv 64 DT) (Z_to_bv 64 (SS + 6 + len)) (Z_to_bv 64 SS)
                           (Z_to_bv 64 (DST + 2 * SEG)) c1 x24 (Z_to_bv 64 (DST + dcap)) x26 x27 (Z_to_bv 64 (DST + 3 * SEG))
                           (Z_to_bv 64 (SS + 6)) (Z_to_bv 64 n) (Z_to_bv 64 (DST + SEG)))
                       F (Z_to_bv 64 0x16138) fc None mm (seg_rom psegs)).
Proof using All.
